export function CardHeader({
  title = "{{title}}",
  subtitle = "{{subtitle}}",
  showAction = {{showAction}},
  color = "{{color}}",
}) {
  return (
    <header style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 10, font: "13px system-ui, sans-serif", color: "#241430", borderBottom: "2px solid " + color, paddingBottom: 10, maxWidth: 300 }}>
      <div>
        <h3 style={{ margin: 0, fontSize: 15 }}>{title}</h3>
        <span style={{ fontSize: 12, opacity: 0.65 }}>{subtitle}</span>
      </div>
      {showAction && (
        <button type="button" aria-label={"More actions for " + title} style={{ border: "1px solid #24143022", background: "#FAF7F2", borderRadius: 6, width: 26, height: 26, cursor: "pointer", flex: "none" }}>
          ⋯
        </button>
      )}
    </header>
  );
}
